// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _caller) public {
        vm.assume(_caller != address(0));
        vm.assume(_caller != address(this));
        vm.assume(c.approvedLoggers(_caller) == false);
        bool returned = c.approvedToLog(_caller);
        assertTrue(returned == false, "approvedToLog should return false for non-approved caller");
    }
}

